        // De Novo Assembly (Shovill)
        assembly = step_2AS_denovo__shovill(ready_reads).assembly

        // AMR Gene Detection (Abricate)
        step_4AN_AMR__abricate(assembly)

        // MLST Typing (MLST)
        step_4TY_MLST__mlst(assembly)

